steps.run:
node -e "
  const p = require('./mingla-business/package.json');
  if (p.scripts?.postinstall !== 'patch-package') {
    console.error('FAIL: mingla-business/package.json scripts.postinstall must equal \"patch-package\", got:', p.scripts?.postinstall);
    process.exit(1);
  }
  if (!p.devDependencies?.['patch-package']) {
    console.error('FAIL: mingla-business/package.json devDependencies must include patch-package');
    process.exit(1);
  }
  console.log('OK: postinstall=\"patch-package\" and patch-package devDependency present (' + p.devDependencies['patch-package'] + ')');
"

